//! Fuel ↔ valve refusal binding — GENERATED by `ggen sync` from the
//! `strata-temprun-pack` ontology (https://strata.chatman.ai/ontology#).
//! Do not edit by hand.
//!
//! COMPOSITION LAW: arena fuel exhaustion emits a valve-taxonomy refusal.
//! The refusal class is declared in the strata-valve-pack ontology
//! (valve:FuelExhaustedRefusal, atom "fuel_exhausted", module
//! `Strata.Valve.Refusals.FuelExhausted`); the IRI is cited here as a
//! pinned constant — no owl:imports, house style. The wire consequence is
//! the valve's opaque 32-byte RefusalReceipt; the
//! arena's `Verdict::Fail` on exhaustion carries that refusal identity on
//! the admission surface.


/// PINNED VALVE IRI — strata-valve-pack ontology.ttl
/// valve:FuelExhaustedRefusal (a valve:RefusalClass). Mirrored constant;
/// gated structurally by gates/020_fuel_refusal_binding.rq.
pub const FUEL_EXHAUSTED_REFUSAL_IRI: &str = "https://strata.chatman.ai/ontology/valve#FuelExhaustedRefusal";

/// Wire length of the valve's opaque RefusalReceipt (bytes). Must equal
/// the valve pack's valve:refusalReceiptLen wire fact (32).
pub const REFUSAL_RECEIPT_LEN: usize = 32;

/// Arenas that emit the pinned refusal on fuel exhaustion.
pub const FUEL_REFUSAL_ARENAS: &[&str] = &[
    "default",
];

/// Fail-closed closure check for the composition binding: the pinned IRI
/// must keep its valve-namespace shape, the receipt length must stay the
/// valve wire constant, and at least one arena must emit the pinned IRI.
pub fn fuel_refusal_binding_closure() -> Result<(), String> {
    if !FUEL_EXHAUSTED_REFUSAL_IRI
        .starts_with("https://strata.chatman.ai/ontology/valve#")
    {
        return Err(format!(
            "wrong_refusal_class: {} is not in the valve namespace",
            FUEL_EXHAUSTED_REFUSAL_IRI
        ));
    }
    if REFUSAL_RECEIPT_LEN != 32 {
        return Err(format!(
            "wrong_receipt_len: {} != the valve wire constant 32",
            REFUSAL_RECEIPT_LEN
        ));
    }
    if FUEL_REFUSAL_ARENAS.is_empty() {
        return Err("unemitted_binding: no arena emits the pinned refusal".to_string());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// COURT — the pinned binding satisfies its own closure law.
    #[test]
    fn binding_is_closed() {
        fuel_refusal_binding_closure().expect("composition binding must be closed");
        assert_eq!(FUEL_EXHAUSTED_REFUSAL_IRI, "https://strata.chatman.ai/ontology/valve#FuelExhaustedRefusal");
        assert_eq!(REFUSAL_RECEIPT_LEN, 32);
        assert!(FUEL_REFUSAL_ARENAS.contains(&"default"));
    }

    /// Sabotage twin — a binding whose IRI is corrupted out of the valve
    /// namespace: the closure check must refuse it. The honest binding
    /// passes on the same instance-shape; divergence is the discrimination.
    #[test]
    fn sabotage_twin_corrupted_iri_is_caught() {
        let honest_iri = FUEL_EXHAUSTED_REFUSAL_IRI;
        let twin_iri = "https://strata.chatman.ai/ontology/not-valve#FuelExhaustedRefusal";
        assert!(honest_iri.starts_with("https://strata.chatman.ai/ontology/valve#"));
        assert!(!twin_iri.starts_with("https://strata.chatman.ai/ontology/valve#"));
    }
}

